def solve_new(gi):
    gi=np.array(gi); go=gi.copy()
    vals,cnt=np.unique(gi,return_counts=True); bg=vals[np.argmax(cnt)]; mk=[v for v in vals if v!=bg][0]
    marks=(gi==mk); rs,cs=np.where(marks)
    r0,r1,c0,c1=rs.min(),rs.max(),cs.min(),cs.max()
    def onborder(i,j): return i in (r0,r1) or j in (c0,c1)
    # 1. border
    for i in range(r0,r1+1):
        for j in range(c0,c1+1):
            if onborder(i,j) and gi[i,j]==bg: go[i,j]=2
    # 2. line gap rule
    R,C=gi.shape
    for orient in ('row','col'):
        nR = R if orient=='row' else C
        for L in range(nR):
            if orient=='row':
                idx=[j for j in range(c0,c1+1) if gi[L,j]==mk]; get=lambda t:(L,t)
            else:
                idx=[i for i in range(r0,r1+1) if gi[i,L]==mk]; get=lambda t:(t,L)
            gaps=[]
            for a,b in zip(idx,idx[1:]):
                if b-a>1: gaps.append(list(range(a+1,b)))
            if not gaps or len(gaps)>2: continue
            if any(len(g)!=1 for g in gaps): continue
            if any(onborder(*get(t)) for g in gaps for t in g): continue
            for g in gaps:
                for t in g:
                    if gi[get(t)[0],get(t)[1]]==bg: go[get(t)]=2
    # 3. extension: qualified lines only — bg between border-2 and mark at line ends
    # recompute qualified lines
    qual=set()
    for orient in ('row','col'):
        nR = R if orient=='row' else C
        for L in range(nR):
            if orient=='row':
                idx=[j for j in range(c0,c1+1) if gi[L,j]==mk]
            else:
                idx=[i for i in range(r0,r1+1) if gi[i,L]==mk]
            gaps=[list(range(a+1,b)) for a,b in zip(idx,idx[1:]) if b-a>1]
            if gaps and len(gaps)<=2 and all(len(g)==1 for g in gaps) \
               and not any(onborder(*((L,t) if orient=='row' else (t,L))) for g in gaps for t in g):
                qual.add((orient,L))
    for (orient,L) in qual:
        if orient=='row':
            seq=[(j, gi[L,j]) for j in range(c0,c1+1)]
        else:
            seq=[(i, gi[i,L]) for i in range(r0,r1+1)]
        # find bg cell sandwiched between a 2 (in go) and a mark, at the two ends
        for t in range(len(seq)):
            i,j=seq[t][0], None
            pos, v = seq[t]
            if v!=bg: continue
            r_,c_ = (L,pos) if orient=='row' else (pos,L)
            if go[r_,c_]!=bg: continue
            # neighbors along line
            if t>0 and t<len(seq)-1:
                pv=go[(L,seq[t-1][0]) if orient=='row' else (seq[t-1][0],L)]
                nv=gi[(L,seq[t+1][0]) if orient=='row' else (seq[t+1][0],L)]
                pv2=gi[(L,seq[t-1][0]) if orient=='row' else (seq[t-1][0],L)]
                nv2=go[(L,seq[t+1][0]) if orient=='row' else (seq[t+1][0],L)]
                if (pv==2 and nv==mk) or (pv==mk and nv2==2): go[r_,c_]=2
    return go

